export const QUIZ_ITEMS = [
  { id: "2665", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما الفرق بين اسمَي الله «الغفور» و«الغفّار»؟", answer: "الغفور: يدل على سعة المغفرة في ذاتها مهما عظمت الذنوب. الغفّار: يدل على كثرة المغفرة وتكرارها مراراً وتكراراً، أي كثير المغفرة لا ينضب عفوه. والاسمان معاً يُعطيان المؤمن رجاءً بسعة المغفرة واستمرارها مهما كان العبد مذنباً وكثُرت عودته بالتوبة.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2666", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "سهل", question: "ما معنى اسم الله «الحليم» وكيف يُفرَّق بينه وبين الصبور؟", answer: "الحليم: الذي لا يستفزه عصيان العصاة ولا يُقلقه انتشار المعاصي، فيؤخر العقوبة رحمةً وحكمةً. الصبور في المقابل: يركز على التأخير الطويل مع الإحاطة بالخلق. الحليم يُشير إلى الطمأنينة التامة وعدم تغيّر حال الله بمعصية عبده.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2667", section: "الأسماء الحسنى", category: "شرح الأسماء", level: "متوسط", question: "ما معنى اسمَي الله «الوكيل» و«الكفيل»؟", answer: "الوكيل: الذي يتولى مصالح عباده ويكفيهم ما يهمهم. قال تعالى: ﴿وَكَفَىٰ بِاللَّهِ وَكِيلاً﴾. ومعناه التفويض التام إليه والاعتماد عليه وحده في جلب المصالح ودرء المفاسد. وهو ضمنياً يتضمن الكفالة والرعاية الكاملة لمن توكل عليه.", explanation: "يُستفاد منه في باب شرح الأسماء. يُستفاد منه في باب شرح الأسماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2668", section: "الأسماء الحسنى", category: "الأسماء الحسنى عموماً", level: "سهل", question: "كم اسماً من أسماء الله الحسنى وردت في الحديث المشهور عند الترمذي وابن ماجه؟", answer: "تسعة وتسعون اسماً في حديث: «إن لله تسعة وتسعين اسماً مئةً إلا واحداً من أحصاها دخل الجنة» (البخاري ومسلم). غير أن العلماء اختلفوا في تعداد تلك الأسماء لأن الحديث في الصحيحين لم يذكرها، بل ذِكرها في رواية الترمذي من زيادة راوٍ يناقشها العلماء.", explanation: "يُستفاد منه في باب الأسماء الحسنى عموماً. يُستفاد منه في باب الأسماء الحسنى عموماً مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2669", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "ما معنى اسم الله «الغفار» و«الغفور»؟ وما الفرق بينهما؟", answer: "الغفور: صيغة مبالغة تدل على عِظَم المغفرة وشمولها — أي أنه يغفر الذنب العظيم. الغفار: صيغة مبالغة تدل على تكرار المغفرة ودوامها — أي أنه يغفر مرة بعد مرة. فالغفور يشير إلى الكمية والعِظَم، والغفار يشير إلى التكرار والاستمرار. قال تعالى: ﴿إِنَّهُ كَانَ غَفَّاراً﴾ (نوح: 10) وقال: ﴿وَهُوَ الْغَفُورُ الرَّحِيمُ﴾.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2670", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما معنى اسم الله «القيوم»؟ وما دلالته الاعتقادية؟", answer: "القيوم: من قام يقوم — صيغة مبالغة تجمع معنيين: 1) القائم بنفسه: أي الغني عن كل شيء الذي لا يحتاج لأحد في وجوده. 2) المُقيم لغيره: أي الذي يقوم على كل مخلوق فيحفظه ويرزقه ويُدبّره. الدلالة الاعتقادية: استقلال الله التام عن خلقه، وحاجة المخلوقات جميعاً إليه. ولذا جُمع مع «الحي» في آية الكرسي: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2671", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "كم عدد أسماء الله الحسنى المذكورة في الحديث النبوي الشريف؟", answer: "تسعة وتسعون (99) اسماً، وردت في حديث أبي هريرة أن النبي ﷺ قال: «إن لله تسعة وتسعين اسماً من أحصاها دخل الجنة»، والمقصود بـ«الإحصاء» معرفتها وحفظها والتعبد لله بمعانيها.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2672", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "ما معنى اسم الله «الرحمن» لغةً واصطلاحاً؟", answer: "الرحمن مشتق من الرحمة، وهو من أبنية المبالغة على وزن فَعْلان مما يدل على السعة والامتلاء، أي ذو الرحمة الواسعة الشاملة لجميع الخلق في الدنيا. واسم الرحمن خاص بالله لا يُطلق على غيره، بخلاف الرحيم الذي وُصف به بعض الناس.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2673", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما الفرق بين اسمَي الله «العزيز» و«القوي»؟", answer: "العزيز: ذو العزة الكاملة، غير المغلوب، الذي يعتز به كل شيء ويحتاج إليه كل شيء. القوي: ذو القوة التامة التي لا تنقص ولا تعتريها غلبة. العزة تتضمن معنى الامتناع وعدم الانكسار، بينما القوة تتضمن الاقتدار والمَكنة.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2674", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما اسم الله الذي يدل على أنه الوحيد المستحق للعبادة؟", answer: "اسم «الإله» أو «الله» بالعلمية. أما في أسماء الله الحسنى: «الواحد» و«الأحد» يدلان على انفراده بالوحدانية. الواحد: المنفرد الذي لا نظير له. الأحد: المنفرد الذي لا يقبل الانقسام ولا الشركة في أي وجه.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2675", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "صعب", question: "ما الفرق بين «الحكيم» و«العليم» من أسماء الله الحسنى؟", answer: "العليم: ذو العلم الشامل بكل شيء ظاهراً وباطناً، ماضياً وحاضراً ومستقبلاً، لا يخفى عليه مثقال ذرة. الحكيم: ذو الحكمة في كل أفعاله وأقواله وأقداره، بمعنى إتقان الأشياء وإحكامها ووضعها في مواضعها اللائقة. فالعلم يتعلق بالمعرفة، والحكمة بحُسن التصرف.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2676", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "صعب", question: "من العلماء الذين ألّفوا كتباً مستقلة في شرح أسماء الله الحسنى؟", answer: "أبرز من ألّف في الأسماء الحسنى: ابن القيم في «مدارج السالكين» وكتابه المستقل «شفاء العليل» وبدائع الفوائد. والبيهقي في «الأسماء والصفات». وابن منده في «التوحيد». والرازي في «لوامع البينات». وفي المعاصرين سعيد حوّى في «الأساس في السنة».", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2677", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما أركان الحج؟", answer: "الإحرام والوقوف بعرفة وطواف الإفاضة والسعي بين الصفا والمروة", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2678", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما الميقات المكاني لأهل المدينة النبوية؟", answer: "ذو الحُلَيفة (أبيار علي)، ويُحرم منه أهل المدينة ومن مرّ به من غيرهم، وهو أبعد المواقيت عن مكة", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2679", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما طواف الإفاضة؟", answer: "طواف الإفاضة (طواف الزيارة): ركن من أركان الحج لا يصحّ الحج بتركه ولا يُجبر بدم — بخلاف الواجب الذي يُجبر بدم — ووقته يوم النحر وما بعده، بعد الوقوف بعرفة. وأصله قوله تعالى: ﴿وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ﴾ (الحج: ٢٩)", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2680", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "كم عدد أشواط السعي بين الصفا والمروة؟", answer: "سبعة أشواط، يبدأ بالصفا وينتهي بالمروة؛ فالذهاب من الصفا إلى المروة شوط، والرجوع من المروة إلى الصفا شوط ثانٍ", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2681", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما معنى الإحرام؟", answer: "نية الدخول في النسك (الحج أو العمرة). والتلبية عندها سنة مؤكدة عند الشافعية والحنابلة، وواجب عند المالكية، وشرطٌ لانعقاد الإحرام عند الحنفية فلا ينعقد عندهم إلا بها أو بما يقوم مقامها", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2682", section: "الحج والعمرة", category: "الحج", level: "صعب", question: "ما الفرق بين القِران والتمتّع والإفراد في الحج؟", answer: "القِران: أن يُحرم بالحج والعمرة معًا بإحرام واحد. التمتّع: أن يُحرم بالعمرة أولاً فيتحلّل منها، ثم يُحرم بالحج في عامه. الإفراد: أن يُحرم بالحج وحده. ويلزم المتمتّع والقارن هَدْيٌ ولا هَدْيَ على المُفرِد، قال تعالى: ﴿فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ﴾ (البقرة: ١٩٦)", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2683", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما الإحصار في الحج؟", answer: "أن يُمنع المُحرِم من إتمام نسكه، فيتحلّل بنحر هَدْي، قال تعالى: ﴿فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ﴾ (البقرة: ١٩٦). وقصره المالكية والشافعية على المنع بالعدوّ، ووسّعه الحنفية فأدخلوا فيه المرض وذهاب النفقة والحبس ونحوها", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2684", section: "الحج والعمرة", category: "أركان الحج", level: "سهل", question: "ما أركان الحج الأساسية؟", answer: "الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي بين الصفا والمروة", explanation: "يُستفاد منه في باب أركان الحج. يُستفاد منه في باب أركان الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2685", section: "الحج والعمرة", category: "مناسك الحج", level: "متوسط", question: "ما يوم عرفة ولماذا يُعدّ أهم أيام الحج؟", answer: "هو التاسع من ذي الحجة، وفيه الوقوف بعرفة الذي هو ركن الحج الأعظم، وصيامه يكفّر سنتين", explanation: "يُستفاد منه في باب مناسك الحج. يُستفاد منه في باب مناسك الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2686", section: "الحج والعمرة", category: "مناسك الحج", level: "سهل", question: "ما الإحرام في الحج؟", answer: "هو النية لأداء نسك الحج أو العمرة مع ترك المحظورات، ويبدأ من الميقات المحدد لكل جهة", explanation: "يُستفاد منه في باب مناسك الحج. يُستفاد منه في باب مناسك الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2687", section: "الحج والعمرة", category: "مناسك الحج", level: "صعب", question: "ما محظورات الإحرام؟", answer: "حلق الشعر، وتقليم الأظافر، ولبس المخيط للرجل، والطيب، والصيد، وعقد النكاح، والرفث", explanation: "يُستفاد منه في باب مناسك الحج. يُستفاد منه في باب مناسك الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2688", section: "الحج والعمرة", category: "رمي الجمرات", level: "متوسط", question: "متى تُرمى جمرة العقبة؟", answer: "ترمى وحدها يوم النحر (العاشر من ذي الحجة)، ثم تُرمى مرة أخرى مع الجمرتين الصغرى والوسطى في كل يوم من أيام التشريق الثلاثة بعد زوال الشمس", explanation: "يُستفاد منه في باب رمي الجمرات. يُستفاد منه في باب رمي الجمرات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2689", section: "الحج والعمرة", category: "مواقيت الحج", level: "صعب", question: "ما مواقيت الحج الزمانية؟", answer: "شوال وذو القعدة وعشر من ذي الحجة، وهي أشهر الحج المذكورة في القرآن", explanation: "يُستفاد منه في باب مواقيت الحج. يُستفاد منه في باب مواقيت الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2690", section: "الحج والعمرة", category: "السعي", level: "سهل", question: "ما مكانة السعي بين الصفا والمروة؟", answer: "ركن من أركان الحج والعمرة لا يصح النسك بدونه، لقوله تعالى: ﴿إن الصفا والمروة من شعائر الله﴾", explanation: "يُستفاد منه في باب السعي. يُستفاد منه في باب السعي مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2691", section: "الحج والعمرة", category: "فريضة الحج", level: "سهل", question: "كم مرة حج النبي ﷺ؟ وما حجة الوداع؟", answer: "حج النبي ﷺ مرة واحدة بعد الهجرة وهي حجة الوداع عام 10هـ (632م)، وكان معه أكثر من مئة ألف من الصحابة. ألقى فيها خطبة الوداع الجامعة.", explanation: "يُستفاد منه في باب فريضة الحج. يُستفاد منه في باب فريضة الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2692", section: "الحج والعمرة", category: "مناسك الحج", level: "متوسط", question: "ما الفرق بين الحج المفرد والقِران والتمتع؟", answer: "المفرد: الإحرام بالحج وحده من الميقات. القِران: الإحرام بالحج والعمرة معاً. التمتع: الإحرام بالعمرة أولاً ثم التحلل منها ثم الإحرام بالحج في أشهره. والثلاثة جائزة بالإجماع، وأفضلها محل خلاف بين المذاهب: الحنابلة يرون التمتع أفضل، والمالكية والشافعية يرون الإفراد أفضل، والحنفية يرون القِران أفضل.", explanation: "يُستفاد منه في باب مناسك الحج. يُستفاد منه في باب مناسك الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2693", section: "الحج والعمرة", category: "أركان الحج", level: "متوسط", question: "ما أركان الحج التي لا يصح إلا بها؟", answer: "أركان الحج أربعة: 1- الإحرام (النية). 2- الوقوف بعرفة وهو أعظم الأركان («الحج عرفة»). 3- طواف الإفاضة (الزيارة). 4- السعي بين الصفا والمروة. وهذا مذهب الشافعية والحنابلة.", explanation: "يُستفاد منه في باب أركان الحج. يُستفاد منه في باب أركان الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2694", section: "الحج والعمرة", category: "الميقات", level: "متوسط", question: "ما ميقات أهل الكويت للحج والعمرة؟", answer: "ميقات أهل الكويت هو ذو الحليفة (أبيار علي) إذا مروا بطريق المدينة، أو ميقات قرن المنازل (السيل الكبير) إذا مروا بالطريق الشمالي السعودي الشرقي. وبعضهم يُحرم من الكويت إن نوى من الجو.", explanation: "يُستفاد منه في باب الميقات. يُستفاد منه في باب الميقات مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2695", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما أركان الحج الأربعة؟ وما الفرق بين الركن والواجب؟", answer: "أركان الحج الأربعة: 1) الإحرام بنية الحج. 2) الوقوف بعرفة — وهو ركن الحج الأعظم. 3) طواف الإفاضة (الزيارة). 4) السعي بين الصفا والمروة. الفرق بين الركن والواجب: الركن — ما لا يصح الحج بتركه مطلقاً (لا يُجبر بدم). الواجب — ما يصح الحج بتركه ويُجبر بدم. والسنن — ما يُثاب على فعله ولا يُعاقب على تركه.", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2696", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما ترتيب أعمال يوم النحر (يوم العيد) في الحج؟", answer: "أعمال يوم النحر بالترتيب: 1) رمي جمرة العقبة الكبرى (بعد منتصف ليلة العيد أو بعد الفجر). 2) ذبح الهدي. 3) حلق الرأس أو التقصير — يرفع الإحرام الأول (إلا النساء والمحرم). 4) طواف الإفاضة (الحلُّ الكامل بعده). 5) السعي (من لم يسعَ بعد طواف القدوم). ويجوز التقديم والتأخير بين هذه الأعمال الثلاثة الأخيرة كما دلّت عليه الأحاديث.", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2697", section: "الرقائق", category: "أخلاق المسلم", level: "سهل", question: "ما أعلى درجات اليقين التي ذكرها الله في القرآن؟", answer: "عين اليقين — ذكرت في سورة التكاثر. وحق اليقين — ذكرت في سورة الواقعة والحاقة. وعلم اليقين — في سورة التكاثر أيضاً.", explanation: "يُستفاد منه في باب أخلاق المسلم. يُستفاد منه في باب أخلاق المسلم مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2698", section: "الرقائق", category: "آداب الكلام", level: "سهل", question: "ما حكم كثرة الكلام بلا فائدة في الإسلام؟", answer: "مكروه ومنهي عنه — قال ﷺ: «من صمت نجا» وقال: «إن من حسن إسلام المرء تركه ما لا يعنيه» — رواه الترمذي.", explanation: "يُستفاد منه في باب آداب الكلام. يُستفاد منه في باب آداب الكلام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2699", section: "الرقائق", category: "آداب المسجد", level: "سهل", question: "بأي رجل يُستحب الدخول للمسجد؟", answer: "بالرجل اليمنى — لحديث: «إذا دخل أحدكم المسجد فليبدأ بيمينه» ومثله الخروج يبدأ باليسرى.", explanation: "يُستفاد منه في باب آداب المسجد. يُستفاد منه في باب آداب المسجد مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2700", section: "الرقائق", category: "الأخلاق الذميمة", level: "متوسط", question: "ما أكبر الكبائر التي حذّر منها النبي ﷺ؟", answer: "سُئل ﷺ: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله، قال: «الإشراك بالله، وعقوق الوالدين» ثم جلس وقال: «ألا وقول الزور، وشهادة الزور» (متفق عليه — رواه البخاري ومسلم عن أبي بكرة)", explanation: "يُستفاد منه في باب الأخلاق الذميمة. يُستفاد منه في باب الأخلاق الذميمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2701", section: "الرقائق", category: "الدعاء", level: "سهل", question: "ما الدعاء المأثور عند الاستيقاظ من النوم؟", answer: "«الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور» — رواه البخاري. أو: «لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير» عشراً.", explanation: "يُستفاد منه في باب الدعاء. يُستفاد منه في باب الدعاء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2702", section: "الرقائق", category: "الذكر والدعاء", level: "سهل", question: "بمَ أرشد النبي ﷺ فاطمة رضي الله عنها لمّا طلبت منه خادماً؟", answer: "قال لها ﷺ: «ألا أدلّك على ما هو خير لك من خادم؟ تسبّحين ثلاثاً وثلاثين، وتحمدين ثلاثاً وثلاثين، وتكبّرين أربعاً وثلاثين حين تأخذين مضجعك» (متفق عليه — رواه البخاري 3705 ومسلم 2727 عن علي بن أبي طالب).", explanation: "يُستفاد منه في باب الذكر والدعاء. يُستفاد منه في باب الذكر والدعاء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2703", section: "الرقائق", category: "التوبة والاستغفار", level: "سهل", question: "ما أفضل صيغة للاستغفار وما تسمى؟", answer: "تسمى سيد الاستغفار: «اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شر ما صنعت، أبوء لك بنعمتك عليّ وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت».", explanation: "يُستفاد منه في باب التوبة والاستغفار. يُستفاد منه في باب التوبة والاستغفار مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2704", section: "الرقائق", category: "التوبة والاستغفار", level: "سهل", question: "ما شروط التوبة الصحيحة من الذنب؟", answer: "ثلاثة شروط: 1- الإقلاع عن الذنب فوراً. 2- الندم على ما فات. 3- العزم على عدم العودة. وإن كان الذنب يتعلق بحق آدمي زُيد شرط رابع: رد الحقوق أو الاستحلال من أصحابها.", explanation: "يُستفاد منه في باب التوبة والاستغفار. يُستفاد منه في باب التوبة والاستغفار مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2705", section: "الرقائق", category: "التزكية", level: "سهل", question: "ما آفة اللسان التي حذّر منها النبي ﷺ حين سُئل عن أكثر ما يُدخل النار؟", answer: "الفم والفرج — قال ﷺ: «أكثر ما يُدخل الناسَ النار الأجوفان: الفم والفرج» (الترمذي ٢٠٠٤، صححه الألباني). واللسان مفتاح الفم ومدخل أعظم الذنوب.", explanation: "يُستفاد منه في باب التزكية. يُستفاد منه في باب التزكية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2706", section: "الرقائق", category: "الزهد", level: "متوسط", question: "عرّف الزهد في الدنيا وما الفرق بينه وبين الفقر؟", answer: "الزهد: ترك ما لا ينفع في الآخرة وإيثار ما فيه رضا الله. وهو حال القلب لا المال؛ فقد كان سليمان ﷺ ذا ملك عظيم وهو زاهد، وقد يكون الفقير حريصاً غير زاهد.", explanation: "يُستفاد منه في باب الزهد. يُستفاد منه في باب الزهد مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2707", section: "الرقائق", category: "أمراض القلوب", level: "متوسط", question: "ما الكبر وما ضابطه عند أهل العلم؟", answer: "قال ﷺ: «الكبر: بطَر الحق وغمط الناس» (رواه مسلم). بطر الحق: رد الحق وعدم قبوله. غمط الناس: احتقارهم. وهو من الكبائر المهلكة للقلب.", explanation: "يُستفاد منه في باب أمراض القلوب. يُستفاد منه في باب أمراض القلوب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2708", section: "الرقائق", category: "التوبة", level: "سهل", question: "ما أفضل وقت للاستغفار وما دليله من السنة؟", answer: "وقت الأسحار قُبيل الفجر — قال الله تعالى: ﴿وَالْمُسْتَغْفِرِينَ بِالْأَسْحَارِ﴾ (آل عمران: 17). وثبت في السنة نزول الرب تبارك وتعالى في كل ليلة إلى السماء الدنيا في الثلث الأخير.", explanation: "يُستفاد منه في باب التوبة. يُستفاد منه في باب التوبة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2709", section: "الرقائق", category: "اليقين", level: "صعب", question: "ما الفرق بين الوسواس القهري الطبي وبين وسواس الشيطان الشرعي؟", answer: "وسواس الشيطان: خاطر إثمي عارض يُقاومه العبد بالذكر والاستعاذة ولا حرج فيه. والوسواس القهري الطبي: حالة مرضية تستدعي العلاج الطبي. وحكمهما يختلف: الأول مُمانَع شرعاً، والثاني مُعالَج طباً.", explanation: "يُستفاد منه في باب اليقين. يُستفاد منه في باب اليقين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2710", section: "الرقائق", category: "التفكر", level: "سهل", question: "ما الساعات التي يُستحب فيها التفكر والتأمل في خلق الله؟", answer: "خير أوقاته بعد صلاة الفجر قبل شروق الشمس، وفي الليل. فقد نزلت عليه ﷺ ذات ليلة آيات ختام سورة آل عمران (في خلق السماوات والأرض واختلاف الليل والنهار) وقال: «لقد أُنزلت عليّ الليلة آيات، ويل لمن قرأها ولم يتفكر فيها» (رواه ابن حبان في صحيحه بإسناد صحيح على شرط مسلم).", explanation: "يُستفاد منه في باب التفكر. يُستفاد منه في باب التفكر مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2711", section: "الرقائق", category: "ذكر الموت", level: "متوسط", question: "ما الحديث الوارد في فضل ذكر الموت وكثرته؟", answer: "قال ﷺ: «أكثروا ذكر هاذم اللذات: الموت» (رواه الترمذي والنسائي، صحيح). والمعنى: قاطع اللذات وهادمها لأنه يُذكّر بزوال النعيم.", explanation: "يُستفاد منه في باب ذكر الموت. يُستفاد منه في باب ذكر الموت مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2712", section: "الرقائق", category: "الخوف والرجاء", level: "متوسط", question: "هل يجوز اليأس من رحمة الله؟ ما حكمه؟", answer: "اليأس من رحمة الله كبيرة من الكبائر — قال الله تعالى: ﴿إِنَّهُ لَا يَيْأَسُ مِن رَّوْحِ اللَّهِ إِلَّا الْقَوْمُ الْكَافِرُونَ﴾ (يوسف: 87). فاليأس من سمات الكافرين، والمؤمن يجمع الخوف والرجاء.", explanation: "يُستفاد منه في باب الخوف والرجاء. يُستفاد منه في باب الخوف والرجاء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2713", section: "الرقائق", category: "المحبة والشوق", level: "سهل", question: "ما علامة محبة الله في قلب العبد؟", answer: "من علاماتها: 1- محبة النبي ﷺ واتباعه. 2- كثرة ذكر الله. 3- إيثار ما يُحب الله على ما يشتهي النفس. 4- الشوق إلى لقاء الله. قال ﷺ: «من أحب لقاء الله أحب الله لقاءه» (البخاري).", explanation: "يُستفاد منه في باب المحبة والشوق. يُستفاد منه في باب المحبة والشوق مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "2714", section: "الرقائق", category: "العبودية", level: "صعب", question: "ما مقام العبودية ولماذا وصف الله نبيه ﷺ بالعبودية في أشرف مقاماته؟", answer: "العبودية لله هي أشرف مقامات الإنسان لأنها غاية الخلق. وصف الله نبيه بالعبد في ثلاثة مقامات عظيمة: الإسراء ﴿سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ﴾، والتحدي ﴿فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِ﴾، والدعوة ﴿وَأَنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ﴾.", explanation: "يُستفاد منه في باب العبودية. يُستفاد منه في باب العبودية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" }
];

