export const FAWAID_ITEMS = [
  { text: "تجب الزكاة في الذهب والفضة والحبوب والثمار والأنعام وعروض التجارة، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "فقه السنة — السيد سابق", author_name: "السيد سابق" },
  { text: "مفتاح الصلاة الطهور، وتحريمها التكبير، وتحليلها التسليم، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "الترمذي ٣ — حسّنه الألباني", author_name: "سنن الترمذي" },
  { text: "من أدرك ركعة من الصلاة مع الإمام فقد أدرك الصلاة، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "لا ضرر ولا ضرار — قاعدة فقهية جامعة في رفع المفسدة، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "ابن ماجه ٢٣٤١ — حسّنه الألباني بمجموع الطرق", author_name: "سنن ابن ماجه" },
  { text: "المشقة تجلب التيسير — من أهم القواعد الفقهية الخمس الكبرى، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "الأشباه والنظائر — ابن نجيم", author_name: "ابن نجيم" },
  { text: "حافظ على قراءة القرآن في الصلاة وخارجها حتى يكون شفيعك يوم القيامة، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما ثبت في السنة الصحيحة.", category: "القرآن", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "إن الذي يتعتع في القرآن وهو عليه شاق له أجران، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "من قرأ حرفاً من كتاب الله فله به حسنة والحسنة بعشر أمثالها، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "الترمذي ٢٩١٠ — صححه الألباني", author_name: "سنن الترمذي" },
  { text: "فتح مكة كان بلا قتال تقريباً — ودخل النبي ﷺ مكة وهو يقرأ: {إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا}. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "صحيح البخاري — كتاب فضائل القرآن، باب الترجيع", author_name: "الإمام البخاري" },
  { text: "خالف الرماة أمر النبي ﷺ بلزوم الجبل في غزوة أحد فانكشف ظهر المسلمين وانقلبت دفة المعركة، وهذا درس عملي يُستفاد من السيرة النبوية في الحياة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "صحيح البخاري، حديث 3039 — كتاب المغازي", author_name: "الإمام البخاري" },
  { text: "معاذ بن جبل أعلم الأمة بالحلال والحرام، وهذا درس عملي يُستفاد من السيرة النبوية في الحياة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..", category: "السيرة", source: "الترمذي ٣٧٩٠ — حسّنه الألباني", author_name: "سنن الترمذي" },
  { text: "أقرب الناس من النبي ﷺ مجلساً يوم القيامة أحاسنهم خلقاً، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "الترمذي ٢٠١٨ عن جابر — حسّنه الألباني", author_name: "سنن الترمذي" },
  { text: "إياكم والجلوس على الطرقات إلا أن تؤدوا حقها، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "زينوا القرآن بأصواتكم؛ وتحسين الصوت بالتلاوة مشروع، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه أبو داود — صحيح الألباني", author_name: "سنن أبي داود" },
  { text: "لا يشكر الله من لا يشكر الناس، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. فليُلزم المسلم العمل بما علم. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "أبو داود ٤٨١١ — صححه الألباني", author_name: "سنن أبي داود" },
  { text: "إن الله يحب إذا عمل أحدكم عملاً أن يتقنه، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه البيهقي — صحيح الألباني", author_name: "شعب الإيمان" },
  { text: "إنما بُعثت لأتمم مكارم الأخلاق، وهذا من مكارم الأخلاق التي أمر بها الشرع. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه البيهقي — صحيح الألباني", author_name: "شعب الإيمان" },
  { text: "الحزن على الماضي مضيعة للحاضر، وهذا من مكارم الأخلاق التي أمر بها الشرع. فليُلزم المسلم العمل بما علم. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "قاعدة نبوية — ابن القيم: مدارج السالكين", author_name: "ابن قيم الجوزية" },
  { text: "العلم النافع يرفع صاحبه ويثمر العمل؛ قال ﷺ: «من سلك طريقًا يلتمس فيه علمًا سهّل الله له به طريقًا إلى الجنة» — مسلم. وأما ألفاظ «العالم والمتعلم شريكان…» فضعيفة فلا يُستقل بها.", category: "طلب العلم", source: "مسلم ٢٦٩٩؛ ضعّف أهل التحقيق الألفاظ المشهورة الأخرى", author_name: "صحيح البخاري" },
  { text: "قيدوا العلم بالكتاب؛ فالكتابة تصون الحفظ من النسيان، وهذا من آداب طلب العلم وأصوله التي يُرجى بها نفع العلم. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "أثر موقوف — رواه الدارمي وابن أبي شيبة، وصححه الحاكم في المستدرك", author_name: "عمر بن الخطاب" },
  { text: "طلب العلم نافع للدنيا والآخرة؛ يُنسب للشافعي: «من أراد الدنيا فعليه بالعلم…» وهو قول مأثور بلا إسناد متصل يُعوَّل عليه، فيُذكر أدباً لا حديثاً. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "نسبة مشهورة للشافعي بلا إسناد متصل معتمد", author_name: "يُنسب للإمام الشافعي" },
  { text: "فوالله لأن يهدي الله بك رجلاً واحداً خير لك من حمر النعم، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الدعوة", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "بلّغوا عني ولو آية؛ فالعلم يزكو بالتبليغ ولو قلّ، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الدعوة", source: "رواه البخاري", author_name: "صحيح البخاري" },
  { text: "تأديب الولد وتعليمه من أعظم الحقوق؛ قال ﷺ: «مروا أولادكم بالصلاة لسبع» — أبو داود، حسّنه الألباني. وأما لفظ «لأن يؤدب أحدكم ولده خير من أن يتصدق بصاع» فضعيف فلا يُستقل به.", category: "التربية", source: "أبو داود ٤٩٥ حسّنه الألباني؛ ضعّف الترمذي وغيره لفظ «خير من أن يتصدق بصاع»", author_name: "صحيح البخاري" },
  { text: "حق الولد على والده أن يحسن اسمه ويحسن تربيته، وهذا من أصول التربية الإسلامية التي يُنشأ عليها الولد. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "رواه البيهقي", author_name: "شعب الإيمان" }
];
